<template><main style="max-width:420px;margin:120px auto;padding:16px"><div class="card" style="padding:24px"><h1>Other sign-in methods</h1><p style="color:#a1a1aa">Username + Password — moved here from main Login Page.</p><input v-model="u" placeholder="Username" class="field" style="width:100%;padding:12px;margin:6px 0" /><input v-model="p" type="password" placeholder="Password" class="field" style="width:100%;padding:12px" /><button class="btn-primary" style="width:100%;margin-top:12px" @click="go">Sign In with Username</button><p><RouterLink to="/login">Back to Sign In</RouterLink></p></div></main></template>
